/* ============================================================================
 * WORKFLOW STAGE HEADER - ENTERPRISE STAGE TITLE BANNER
 * Reusable Custom Widget for Stage/Phase Header Banner across all workflow pages.
 * ============================================================================ */
:root {
  --color-badge: #2563eb;
  --color-title: #0f172a;
  --color-subtitle: #64748b;
  --color-bg-white: #ffffff;
}

html, body, #root {
  box-sizing: border-box;
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  margin: 0;
  padding: 0;
  width: 100%;
  height: auto;
  background: transparent;
  overflow: hidden !important;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

html::-webkit-scrollbar, body::-webkit-scrollbar, #root::-webkit-scrollbar,
.stage-header-container::-webkit-scrollbar, .stage-header-container *::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

.stage-header-container, .stage-header-container * {
  box-sizing: border-box;
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.stage-header-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
  padding: 16px 24px;
  background: #ffffff;
  border-radius: 8px;
}

.stage-phase-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  color: #2563eb;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  line-height: 1.2;
}

.stage-title {
  font-size: 28px;
  font-weight: 800;
  color: #0f172a;
  margin: 0;
  line-height: 1.25;
  letter-spacing: -0.3px;
}

.stage-subtitle {
  font-size: 13px;
  font-weight: 400;
  color: #64748b;
  line-height: 1.5;
  margin: 0;
  max-width: 950px;
}

