import React, { useState, useEffect } from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm';
import ReactDOM from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm';

// Dynamic AppSmith Model Parser
const parseAppsmithModel = modelRaw => {
  if (!modelRaw) return {};
  let parsed = modelRaw;
  if (typeof modelRaw === 'string') {
    try {
      parsed = JSON.parse(modelRaw);
    } catch (e) {}
  }
  return parsed || {};
};
function WorkflowStageHeader() {
  const [modelData, setModelData] = useState(() => parseAppsmithModel(window.appsmith?.model));
  useEffect(() => {
    if (window.appsmith?.onModelChange) {
      window.appsmith.onModelChange(m => {
        if (!m) return;
        setModelData(parseAppsmithModel(m));
      });
    }
  }, []);
  const phaseBadge = modelData.phaseBadge || modelData.phaseText || 'PHASE 02 — SPECIFICATIONS & ALIGNMENT VERIFICATION';
  const title = modelData.title || modelData.titleText || 'Agent Consistency Validation Hub';
  const subtitle = modelData.subtitle || modelData.subtitleText || modelData.description || 'Sequential multi-agent verification check auditing scope, timeline, Bill of Quantities (BOQ), technical spec compliance, asset registries, approved vendor manufacturer lists (AML), and drawdown authorizations.';
  return React.createElement('div', {
    className: 'stage-header-container'
  }, phaseBadge ? React.createElement('div', {
    className: 'stage-phase-badge'
  }, phaseBadge) : null, title ? React.createElement('h1', {
    className: 'stage-title'
  }, title) : null, subtitle ? React.createElement('p', {
    className: 'stage-subtitle'
  }, subtitle) : null);
}
appsmith.onReady(() => {
  ReactDOM.render(React.createElement(WorkflowStageHeader, null), document.getElementById('root'));
});

